/** আজকের তারিখ (ডিভাইসের স্থানীয় সময়ে, YYYY-MM-DD) — UTC নয়, যাতে দিন সঠিক সময়ে বদলায় */
export function getLocalDateStr(d: Date = new Date()): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export const DAILY_EXP_GOAL = 40;

export function getSpiritualLevel(points: number) {
  const currentLevel = SPIRITUAL_LEVELS.slice().reverse().find(l => points >= l.minPoints) || SPIRITUAL_LEVELS[0];
  const nextLevel = SPIRITUAL_LEVELS.find(l => l.id === currentLevel.id + 1);
  const progressInLevel = nextLevel 
    ? Math.min(100, Math.max(0, Math.round(((points - currentLevel.minPoints) / (nextLevel.minPoints - currentLevel.minPoints)) * 100)))
    : 100;

  return {
    currentLevel,
    nextLevel,
    progressInLevel,
    pointsNeeded: nextLevel ? Math.max(0, nextLevel.minPoints - points) : 0,
  };
}

