    "benefit": "আবূ হুরাইরাহ (রাঃ) হতে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে ব্যক্তি দিনের মধ্যে একশ’ বার পড়বে ‘আল্লাহ ছাড়া আর কোন ইলাহ নেই, তিনি এক, তাঁর কোন অংশীদার নেই। রাজত্ব একমাত্র তাঁরই, প্রশংসা তাঁরই, তিনি সব কিছুর উপর সর্বশক্তিমান।’ সে দশটি গোলাম মুক্ত করার সাওয়াব লাভ করবে এবং তার জন্য একশ’টি নেকী লেখা হবে, আর তার একশ’টি গুনাহ মিটিয়ে দেয়া হবে। আর সে দিন সন্ধ্যা অবধি এটা তার জন্য রক্ষাকবচ হবে এবং তার চেয়ে অধিক ফাযীলাতপূর্ণ ‘আমল আর কারো হবে না। তবে সে ব্যক্তি ছাড়া যে ব্যক্তি এ ‘আমল তার চেয়েও অধিক করবে।",
    "reference": "সহীহ বুখারী: ৬৪০৩",
