    "arabic": "اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً",
    "benefit": "'আবদুল্লাহ ইবনু উমার (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, একদিন আমরা রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর সালাত আদায় করেছিলাম। এমন সময় এক ব্যক্তি বলে উঠলঃ “আল্লহু আকবার কাবীরা- ওয়াল হামদুলিল্লা-হি কাসীরা- ওয়া সুবহা-নাল্ল-হি বুকরাতান ওয়া আসীলা-” (অর্থাৎ- আল্লাহ সর্বশ্রেষ্ঠ, বড়। সব প্রশংসা আল্লাহর। আর সকাল ও সন্ধ্যায় তারই পবিত্রতা বর্ণনা করতে হবে।)। (সালাত শেষে) রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম জিজ্ঞেস করলেন, এ কথাগুলো কে বলল? সবার মধ্যে থেকে জনৈক ব্যক্তি বললঃ হে আল্লাহর রসূল আমি ঐ কথাগুলো বলেছি। তখন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেন, কথাগুলো আমার কাছে বিস্ময়কর মনে হয়েছে। কারণ কথাগুলোর জন্য আসমানের দরজা খুলে দেয়া হয়েছিল।",
    "reference": "সহীহ মুসলিম: ৬০১",
