    "title": "সাইয়্যিদুল ইস্তিগফার পাঠ (শ্রেষ্ঠ ক্ষমা প্রার্থনা)",
    "arabic": "اللَّهُمَّ أَنْتَ رَبِّي، لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَىَّ وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ",
    "benefit": "শাদ্দাদ ইবনু আউস (রাঃ) হতে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ সাইয়্যিদুল ইস্তিগফার হলো বান্দার এ দু‘আ পড়া- ‘‘হে আল্লাহ! তুমি আমার প্রতিপালক। তুমিই আমাকে সৃষ্টি করেছ। আমি তোমারই গোলাম। আমি যথাসাধ্য তোমার সঙ্গে কৃত প্রতিজ্ঞা ও অঙ্গীকারের উপর আছি। আমি আমার সব কৃতকর্মের কুফল থেকে তোমার কাছে আশ্রয় চাচ্ছি। তুমি আমার প্রতি তোমার যে নি‘য়ামত দিয়েছ তা স্বীকার করছি। আর আমার কৃত গুনাহের কথাও স্বীকার করছি। তুমি আমাকে ক্ষমা কর।’’ যে ব্যক্তি দিনে (সকালে) দৃঢ় বিশ্বাসের সঙ্গে এ ইসতিগফার পড়বে আর সন্ধ্যা হবার আগেই সে মারা যাবে, সে জান্নাতী হবে। আর যে ব্যক্তি রাতে (প্রথম ভাগে) দৃঢ় বিশ্বাসের সঙ্গে এ দু‘আ পড়ে নেবে আর সে ভোর হবার আগেই মারা যাবে সে জান্নাতী হবে।",
    "reference": "সহীহ বুখারী: ৬৩০৬",
    "durationMinutes": 1,
    "points": 4,
    "category": "dua",
    "timing": "দিনে (সকালে) ও রাতে"
