    "benefit": "আনাস (রাঃ) হতে বর্ণিত আছে, তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এই দু’আ অধিক পাঠ করতেনঃ হে অন্তরসমূহের পরিবর্তনকারী! আমার অন্তরকে তোমার দ্বীনের উপর প্রতিষ্ঠিত (দৃঢ়) রাখো। আমি বললাম, হে আল্লাহর রাসূল (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম)। আমরা ঈমান এনেছি আপনার উপর এবং আপনি যা নিয়ে এসেছেন তার উপর। আপনি আমাদের ব্যাপারে কি কোনরকম আশংকা করেন? তিনি বললেনঃ হ্যাঁ, কেননা, আল্লাহ তা'আলার আঙ্গুলসমূহের মধ্যকার দুটি আঙ্গুলের মাঝে সমস্ত অন্তরই অবস্থিত। তিনি যেভাবে ইচ্ছা তা পরিবর্তন করেন।",
    "reference": "জামে তিরমিজি: ২১৪০ (আলবানী: সহীহ)",
