    "benefit": "আনাস ইবনু মালিক (রাযিঃ) হতে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ কোন লোক জান্নাতের জন্য আল্লাহ তা'আলার নিকট তিনবার প্রার্থনা করলে জান্নাত তখন বলে, হে আল্লাহ! তাকে জান্নাতে প্রবেশ করান। আর কোন লোক তিনবার জাহান্নাম হতে পানাহ (আশ্রয়) চাইলে জাহান্নাম তখন আল্লাহ তা'আলার নিকট বলে, হে আল্লাহ! তাকে জাহান্নাম থেকে মুক্তি দিন।",
    "reference": "জামে তিরমিজি: ২৫৭২ (আলবানী: সহীহ) / সুনানে আবু দাউদ: ৭৯২ (আলবানী: সহীহ)",
