    "benefit": "‘আলী (রাযিঃ) হতে বর্ণিত আছে, একটি চুক্তিবদ্ধ গোলাম তার নিকটে এসে বলে, আমার চুক্তির অর্থ পরিশোধ করতে আমি অপরাগ হয়ে পড়েছি। আমাকে আপনি সহযোগিতা করুন। তিনি বললেন, আমি তোমাকে কি এমন একটি বাক্য শিখিয়ে দিব না যা আমাকে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম শিখিয়েছিলেন? যদি তোমার উপর সীর (সাবীর) পর্বত পরিমাণ ঋণও থাকে তবে আল্লাহ তা'আলা তোমাকে তা পরিশোধের ব্যবস্থা করে দিবেন। তিনি বলেনঃ তুমি বল, “হে আল্লাহ! তোমার হালালের মাধ্যমে আমাকে তোমার হারাম হতে বিরত রাখ বা দূরে রাখ এবং তোমার দয়ায় তুমি ব্যতীত অন্যের মুখাপেক্ষী হওয়া হতে আমাকে আত্মনির্ভরশীল কর”।",
