    "benefit": "উম্মু সালামাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, আমি রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছিঃ কোন মুসলিমের ওপর মুসীবাত আসলে যদি সে বলেঃ আল্লাহ যা হুকুম করেছেন- \"ইন্না- লিল্লা-হি ওয়া ইন্না- ইলায়হি র-জিউন” (অর্থাৎ- আমরা আল্লাহরই জন্যে এবং তারই কাছে ফিরে যাব) বলে এবং এ দু'আ পাঠ করে- “আল্ল-হুম্মা' জুৱনী ফী মুসীবাতী ওয়া আখলিফ লী খয়রাম মিনহা- ইল্লা- আখলাফাল্ল-হু লাহ খয়রাম মিনহা-” (অর্থাৎ- হে আল্লাহ! আমাকে আমার মুসীবাতে সাওয়াব দান কর এবং এর বিনিময়ে এর চেয়ে উত্তম বস্তু দান কর, তবে মহান আল্লাহ তাকে এর চেয়ে উত্তম বস্তু দান করে থাকেন।)।",
