    "arabic": "اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا ��َلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ",
    "benefit": "আবূ বাকর সিদ্দীক (রাযি.) হতে বর্ণিত। একদা তিনি আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম -এর নিকট আরয করলেন, আমাকে সালাতে পাঠ করার জন্য একটি দু‘আ শিখিয়ে দিন। তিনি বললেন, এ দু‘আটি বলবে- قُلْ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا وَلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي إِنَّك أَنْتَ الْغَفُورُ الرَّحِيمُ ‘‘হে আল্লাহ্! আমি নিজের উপর অধিক জুলুম করেছি। আপনি ছাড়া সে অপরাধ ক্ষমা করার আর কেউ নেই। আপনার পক্ষ হতে আমাকে তা ক্ষমা করে দিন এবং আমার উপর রহমত বর্ষণ করুন। নিশ্চয়ই আপনি ক্ষমাশীল ও দয়াবান।’’",
