    "arabic": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾",
    "banglaMeaning": "(১) শুরু করছি আল্লাহর নামে যিনি পরম করুণাময়, অতি দয়ালু। (২) যাবতীয় প্রশংসা আল্লাহ তাআলার যিনি সকল সৃষ্টি জগতের পালনকর্তা। (৩) যিনি নিতান্ত মেহেরবান ও দয়ালু। (৪) যিনি বিচার দিনের মালিক। (৫) আমরা একমাত্র তোমারই ইবাদত করি এবং শুধুমাত্র তোমারই সাহায্য প্রার্থনা করি। (৬) আমাদেরকে সরল পথ দেখাও, (৭) সে সমস্ত লোকের পথ, যাদেরকে তুমি নেয়ামত দান করেছ। তাদের পথ নয়, যাদের প্রতি তোমার গজব নাযিল হয়েছে এবং যারা পথভ্রষ্ট হয়েছে।",
    "benefit": "আবূ হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। … কেননা আমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম কে বলতে শুনেছি, মহান আল্লাহ বলেছেনঃ আমার এবং আমার বান্দার মাঝে আমি সালাতকে অর্ধেক অর্ধেক করে ভাগ করে নিয়েছি এবং আমার বান্দার জন্য রয়েছে সে যা চায়। বান্দা যখন বলে, الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ (সমস্ত প্রশংসা বিশ্ব জাহানের প্রতিপালক আল্লাহর জন্য), আল্লাহ তা'আলা তখন বলেনঃ আমার বান্দা আমার প্রশংসা করেছে।",
