    "banglaMeaning": "(১) বলুন, তিনি আল্লাহ, এক, (২) আল্লাহ অমুখাপেক্ষী, (৩) তিনি কাউকে জন্ম দেননি এবং কেউ তাকে জন্ম দেয়নি (৪) এবং তার সমতুল্য কেউ নেই।",
    "benefit": "আবূ সা‘ঈদ খুদরী (রাঃ) হতে বর্ণিত যে, এক ব্যক্তি আরেক ব্যক্তিকে ‘কুল হুআল্লাহু আহাদ’ পড়তে শুনলেন। সে বার বার তা মুখে উচ্চারণ করছিল। পরদিন সকালে তিনি রাসূলুল্লাহ্ সাল্লাল্লাহু ‘আলাইহি ওয়াসাল্লাম-এর কাছে এসে এ ব্যাপারে বললেন। যেন ঐ ব্যক্তি তাকে কম মনে করলেন। তখন রাসূল সাল্লাল্লাহু ‘আলাইহি ওয়াসাল্লাম বললেন, সেই সত্তার কসম, যাঁর হাতে আমার জীবন। এ সূরাহ হচ্ছে সমগ্র কুরআনের এক-তৃতীয়াংশের সমান।",
