    "arabic": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾ • بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾ • بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾",
    "banglaMeaning": "(১) বলুন, তিনি আল্লাহ, এক, (২) আল্লাহ অমুখাপেক্ষী, (৩) তিনি কাউকে জন্ম দেননি এবং কেউ তাকে জন্ম দেয়নি (৪) এবং তার সমতুল্য কেউ নেই। • (১) বলুন, আমি আশ্রয় গ্রহণ করছি প্রভাতের পালনকর্তার, (২) তিনি যা সৃষ্টি করেছেন, তার অনিষ্ট থেকে, (৩) অন্ধকার রাত্রির অনিষ্ট থেকে, যখন তা সমাগত হয়, (৪) গ্রন্থিতে ফুঁৎকার দিয়ে জাদুকারিনীদের অনিষ্ট থেকে (৫) এবং হিংসুকের অনিষ্ট থেকে যখন সে হিংসা করে। • (১) বলুন, আমি আশ্রয় গ্রহণ করিতেছি মানুষের পালনকর্তার, (২) মানুষের অধিপতির, (৩) মানুষের মা’বুদের (৪) তার অনিষ্ট থেকে, যে কুমন্ত্রণা দেয় ও আত্নগোপন করে, (৫) যে কুমন্ত্রণা দেয় মানুষের অন্তরে (৬) জ্বিনের মধ্য থেকে অথবা মানুষের মধ্য থেকে।",
    "benefit": "মু‘আয ইবনু আব্দুল্লাহ ইবনু খুবাইব (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। তিনি বলেন, এক বর্ষণমুখর খুবই অন্ধকার কালো রাতে আমাদের সালাত পড়ার জন্য আমরা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে খুঁজছিলাম। আমরা তাঁকে পেয়ে গেলাম। তিনি বললেনঃ বলো। আমি কিছুই বললাম না। পুনরায় তিনি বললেন, বলো। আমি কিছুই বললাম না। তিনি আবার বললেনঃ বলো। তখন আমি বললাম, হে আল্লাহর রাসূল! কি বলবো? তিনি বললেনঃ তুমি সন্ধ্যায় ও সকালে উপনীত হয়ে তিনবার সূরা কুল হুয়াল্লাহু (সূরা ইখলাস), সূরা নাস ও ফালাক পড়বে; এতে তুমি যাবতীয় অনিষ্ট থেকে রক্ষা পাবে।",
