    "id": "amal-56",
    "title": "ঘুমানোর আগে সূরা কাফিরূন",
    "arabic": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ قُلْ يَا أَيُّهَا الْكَافِرُونَ ﴿١﴾ لَا أَعْبُدُ مَا تَعْبُدُونَ ﴿٢﴾ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾ وَلَا أَنَا عَابِدٌ مَا عَبَدْتُمْ ﴿٤﴾ وَلَا أَنْتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٥﴾ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ﴿٦﴾",
    "banglaMeaning": "(১) বলুন, হে কাফেরকূল, (২) আমি এবাদত করিনা, তোমরা যার এবাদত কর। (৩) এবং তোমরাও এবাদতকারী নও, যার এবাদত আমি করি (৪) এবং আমি এবাদতকারী নই, যার এবাদত তোমরা কর। (৫) তোমরা এবাদতকারী নও, যার এবাদত আমি করি। (৬) তোমাদের কর্ম ও কর্মফল তোমাদের জন্যে এবং আমার কর্ম ও কর্মফল আমার জন্যে।",
    "benefit": "ফারওয়াহ ইবনু নাওফাল (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম নাওফাল (রাঃ)-কে বলেনঃ তুমি ‘‘কুল ইয়া আয়্যুহাল কাফিরূন’’ সূরাটি পড়ে ঘুমাবে। কেননা তা শিরক থেকে মুক্তকারী।",
    "reference": "সূরা কাফিরূন • অনুবাদ: মুহিউদ্দীন খান / সুনানে আবু দাউদ: ৫০৫৫ (আলবানী: সহীহ)",
    "durationMinutes": 1,
