    "arabic": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ﴿١﴾ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ ﴿٢﴾ لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ ﴿٣﴾ تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ ﴿٤﴾ سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ ﴿٥﴾",
    "banglaMeaning": "(১) আমি একে নাযিল করেছি শবে-কদরে। (২) শবে-কদর সমন্ধে আপনি কি জানেন? (৩) শবে-কদর হল এক হাজার মাস অপেক্ষা শ্রেষ্ঠ। (৪) এতে প্রত্যেক কাজের জন্যে ফেরেশতাগণ ও রূহ অবতীর্ণ হয় তাদের পালনকর্তার নির্দেশক্রমে। (৫) এটা নিরাপত্তা, যা ফজরের উদয় পর্যন্ত অব্যাহত থাকে।",
    "benefit": "রাসূলুল্লাহ ﷺ বলেছেন: আল্লাহ তা'আলার কিতাবের একটি হরফ যে ব্যক্তি পাঠ করবে তার জন্য এর সাওয়াব আছে। আর সাওয়াব হয় তার দশ গুণ হিসেবে। (জামে তিরমিজি: ২৯১০ — সহীহ, আলবানী)",
