    "benefit": "আবূ হুরাইরাহ্ (রাঃ) হতে বর্ণিত। তিনি বলেন, আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেন যে, মানুষের প্রত্যেক জোড়ার প্রতি সদাকাহ রয়েছে, প্রতি দিন যাতে সূর্য উদিত হয় দু’জন লোকের মধ্যে সুবিচার করাও সদাকাহ, কাউকে সাহায্য করে সাওয়ারীতে আরোহণ করিয়ে দেয়া বা তার উপরে তার মালপত্র তুলে দেয়াও সদাকাহ, ভাল কথাও সদাকাহ, সালাত আদায়ের উদ্দেশে পথ চলায় প্রতিটি কদমেও সদাকাহ, রাস্তা থেকে কষ্টদায়ক বস্তু অপসারণ করাও সদাকাহ।",
