    "benefit": "আবূ হুরাইরাহ (রাঃ) হতে বর্ণিত। তিনি বলেন, এক লোক রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর নিকট এসে জিজ্ঞেস করলঃ হে আল্লাহর রাসূল! আমার নিকট কে উত্তম ব্যবহার পাওয়ার অধিক হকদার? তিনি বললেনঃ তোমার মা। লোকটি বললঃ অতঃপর কে? নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ তোমার মা। সে বললঃ অতঃপর কে? তিনি বললেন, তোমার মা। সে বললঃ অতঃপর কে? তিনি বললেনঃ অতঃপর তোমার বাপ।",
