    "benefit": "আবূ হুরাইরাহ্ (রাযি.) হতে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম একদা ফজরের সালাতের সময় বিলাল (রাযি.)-কে জিজ্ঞেস করলেন, হে বিলাল! ইসলাম গ্রহণের পর সর্বাধিক সন্তুষ্টিব্যঞ্জক যে ‘আমল তুমি করেছ, তার কথা আমার নিকট ব্যক্ত কর। কেননা, জান্নাতে (মি’রাজের রাতে) আমি আমার সামনে তোমার পাদুকার আওয়াজ শুনতে পেয়েছি। বিলাল (রাযি.) বললেন, আমার নিকট এর চেয়ে (অধিক) সন্তুষ্টিব্যঞ্জক হয় এমন কিছুতো আমি করিনি। দিন রাতের যে কোন প্রহরে আমি তাহারাত ও পবিত্রতা অর্জন করেছি, তখনই সে তাহারাত দ্বারা সালাত আদায় করেছি, যে পরিমাণ সালাত আদায় করা আমার তাক্দীরে লেখা ছিল।",
