    "banglaMeaning": "আল্লাহর রহমতেই আপনি তাদের জন্য কোমল হৃদয় হয়েছেন পক্ষান্তরে আপনি যদি রাগ ও কঠিন হৃদয় হতেন তাহলে তারা আপনার কাছ থেকে বিচ্ছিন্ন হয়ে যেতো। কাজেই আপনি তাদের ক্ষমা করে দিন এবং তাদের জন্য মাগফেরাত কামনা করুন এবং কাজে কর্মে তাদের পরামর্শ করুন। অতঃপর যখন কোন কাজের সিদ্ধান্ত গ্রহণ করে ফেলেন, তখন আল্লাহ তা’আলার উপর ভরসা করুন আল্লাহ তাওয়াক্কুল কারীদের ভালবাসেন।",
    "benefit": "রাসূলুল্লাহ ﷺ বলেছেন: আল্লাহ তা'আলার কিতাবের একটি হরফ যে ব্যক্তি পাঠ করবে তার জন্য এর সাওয়াব আছে। আর সাওয়াব হয় তার দশ গুণ হিসেবে। (জামে তিরমিজি: ২৯১০ — সহীহ, আলবানী)",
