    "title": "সন্ধ্যার জিকির: ‘আমসাইনা ওয়া আমসাল মুলকু লিল্লাহ…’",
    "arabic": "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ وَالْحَمْدُ لِلَّهِ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ — لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ اللَّهُمَّ أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ وَأَعُوذُ بِكَ مِنْ شَرِّ هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ",
    "benefit": "আবদুল্লাহ ইবনু মাসউদ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, যখন সন্ধ্যা হত তখন রসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলতেনঃ “আম্‌সাইনা- ওয়া আম্‌সাল মুল্‌কু লিল্লা-হি ওয়াল হাম্‌দু লিল্লা-হি লা-ইলা-হা ইল্লাল্ল-হু ওয়াহদাহু লা-শারীকা লাহু”, অর্থাৎ- “আমরা সন্ধ্যায় উপনীত হয়েছি এবং আল্লাহর রাজ্যও, প্রশংসা একমাত্র আল্লাহর জন্য, তিনি ছাড়া কোন মা’বুদ নেই। তিনি একক সত্তা, তার কোন শারীক নেই।” হাসান (রহঃ) বলেন, আমাকে যুবায়দ (রহঃ) হাদীস বর্ণনা করেন যে, তিনি ইবরাহীম (রহঃ) হতে এ দু’আটি মুখস্থ করেছেনঃ “লাহুল মুল্‌কু ওয়ালাহুল হাম্‌দু ওয়াহুয়া আলা- কুল্লি শাইয়িন কদীর, আল্ল-হুম্মা আসআলুকা খইরা হা-যিহিল লাইলাতি ওয়া আউযুবিকা মিন্‌ শাররি হা-যিহিল লাইলাতি ওয়া শাররি মা-বাদাহা আল্ল-হুম্মা ইন্নী আউযুবিকা মিনাল কাসালি ওয়া সূয়িল কিবারি, আল্ল-হুম্মা ইন্নী আউযুবিকা মিন আযা-বিন ফিন্না-রি ওয়া আযা-বিন ফিল কবরি।” অর্থাৎ, “রাজত্ব তার মালিকানাধীন, সকল প্রশংসা তারই, তিনিই সকল কিছুর উপর ক্ষমতবান। হে আল্লাহ! আমি আপনার নিকট এ রাতের কল্যাণ প্রত্যাশা করি এবং আশ্রয় চাই এ রাতের খারাবী হতে এবং এর পরবর্তী রাতের অনিষ্ট থেকেও। হে আল্লাহ! আমি আপনার নিকট আশ্রয় চাই অলসতা থেকে ও অহংকারের খারাবী থেকে। হে আল্লাহ! আমি আপনার নিকট আশ্রয় চাই জাহান্নামের শাস্তি থেকে এবং কবরের শাস্তি থেকে।\"",
    "reference": "সহীহ মুসলিম: ২৭২৩",
    "durationMinutes": 2,
    "points": 4,
    "category": "dua",
    "timing": "সন্ধ্যায়",
    "pronunciation": "আম্‌সাইনা- ওয়া আম্‌সাল মুল্‌কু লিল্লা-হি ওয়াল হাম্‌দু লিল্লা-হি লা-ইলা-হা ইল্লাল্ল-হু ওয়াহদাহু লা-শারীকা লাহু"
