    "arabic": "اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ — اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ",
    "benefit": "আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম ভোরে উপনীত হয়ে বলতেনঃ ‘‘হে আল্লাহ! আপনার অনুগ্রহে আমরা ভোরে উপনীত হই, সন্ধ্যায় উপনীত হই এবং বাঁচি ও মরি। আর আপনার দিকেই আমাদের প্রত্যাবর্তন।’’ আর তিনি যখন সন্ধ্যায় উপনীত হতেন তখন বলতেনঃ ‘‘হে আল্লাহ! আপনারই সাহায্যে আমরা সন্ধ্যায় উপনীত হই এবং সকালে উপনীত হই, আপনার নামেই আমরা বাঁচি ও মরি এবং আপনারই দিকে আমাদের প্রত্যাবর্তন।",
