    "arabic": "اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ",
    "benefit": "আবূ হুরাইরাহ (রাযিঃ) হতে বর্ণিত আছে। তিনি বলেন, আবূ বাকর (রাযিঃ) বললেন, হে আল্লাহর রাসূল! আমাকে এমন কিছুর হুকুম দিন যা আমি সকালে ও বিকেলে উপনীত হয়ে বলতে পারি। তিনি বললেনঃ তুমি বল, “হে আল্লাহ! অদৃশ্য ও দৃশ্যের পরিজ্ঞাত, আকাশ ও যামীনের সৃষ্টিকর্তা, প্রতিটি জিনিসের প্রতিপালক ও মালিক, আমি সাক্ষ্য দেই যে, তুমি ছাড়া কোন মা'বূদ নেই। আমি আমার শরীরের ক্ষতি হতে এবং শাইতানের ক্ষতি ও শিরকি কার্যকালাপ হতে তোমার কাছে আশ্রয় প্রার্থনা করি।” রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ তুমি এই দু’আ সকালে, বিকেলে ও শয্যা গ্রহণকালে পাঠ করবে।",
