    "benefit": "‘আলী (রাঃ) হতে বর্ণিত যে, ফাতিমাহ (রাঃ) যাঁতা চালানোর কষ্ট সম্পর্কে একদা অভিযোগ প্রকাশ করলেন। … তিনি বললেন, তোমরা যা চেয়েছিলে আমি কি তার চেয়েও উত্তম জিনিস শিক্ষা দিব না? তোমরা যখন ঘুমানোর উদ্দেশে বিছানায় যাবে তখন চৌত্রিশ বার ‘‘আল্লাহ্ আকবার’’ তেত্রিশবার ‘‘সুবহানাল্লাহ’’ তেত্রিশবার ‘‘আল হামদুলিল্লাহ’’ পড়ে নিবে। এটা খাদিম অপেক্ষা অনেক উত্তম।",
