    "arabic": "بِاسْمِكَ رَبِّ وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ",
    "benefit": "আবূ হুরাইরাহ (রাঃ) হতে বর্ণিত। তিনি বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যদি তোমাদের কোন ব্যক্তি শয্যা গ্রহণ করতে যায়, তখন সে যেন তার লুঙ্গির ভেতর দিক দিয়ে নিজ বিছানাটা ঝেড়ে নেয়। কারণ, সে জানে না যে, বিছানার উপর তার অনুপস্থিতিতে পীড়াদায়ক কোন কিছু আছে কিনা। তারপর পড়বেঃ হে আমার রবব! আপনারই নামে আমার শরীরটা বিছানায় রাখলাম এবং আপনারই নামে আবার উঠবো। যদি আপনি ইতোমধ্যে আমার জান কবয করে নেন তা হলে, তার উপর রহম করবেন। আর যদি তা আমাকে ফিরিয়ে দেন, তবে তাকে এমনভাবে হিফাযত করবেন, যেভাবে আপনি আপনার নেক বান্দাদের হিফাযাত করে থাকেন।",
