    "title": "ওযু করে ডান কাতে শুয়ে ঘুমের দুআ (শেষ কথা)",
    "arabic": "اللَّهُمَّ أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، اللَّهُمَّ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ",
    "benefit": "বারাআ ইবনু ‘আযিব (রাযি.) হতে বর্ণিত। তিনি বলেনঃ নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যখন তুমি বিছানায় যাবে তখন সালাতের উযূর মতো উযূ করে নেবে। তারপর ডান পাশে শুয়ে বলবেঃ ‘‘হে আল্লাহ! আমার জীবন আপনার নিকট সমর্পণ করলাম। আমার সকল কাজ তোমার নিকট অর্পণ করলাম এবং আমি তোমার আশ্রয় গ্রহণ করলাম তোমার প্রতি আগ্রহ ও ভয় নিয়ে। তুমি ব্যতীত প্রকৃত কোন আশ্রয়স্থল ও পরিত্রাণের স্থান নেই। হে আল্লাহ! আমি ঈমান আনলাম তোমার অবতীর্ণ কিতাবের উপর এবং তোমার প্রেরিত নবীর প্রতি।’’ অতঃপর যদি সে রাতেই তোমার মৃত্যু হয় তবে ইসলামের উপর তোমার মৃত্যু হবে। এ কথাগুলো তোমার সর্বশেষ কথায় পরিণত কর।",
    "reference": "সহীহ বুখারী: ২৪৭",
