    "arabic": "أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ",
    "benefit": "উমার ইবনুল খাত্তাব (রাঃ) হতে বর্ণিত আছে, তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে ব্যক্তি সুন্দরভাবে ওযু করার পর বলেঃ “আমি সাক্ষ্য দিচ্ছি আল্লাহ তা'আলা ব্যতিত আর কোন ইলাহ নেই, তিনি এক, তার কোন শরীক নেই; আমি আরো সাক্ষ্য দিচ্ছি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার বান্দাহ ও তারই রাসূল; হে আল্লাহ! আমাকে তাওবাকারীদের অন্তর্ভুক্ত কর এবং আমাকে পবিত্রতা অর্জনকারীদের অন্তর্ভুক্ত কর”, তার জন্য জান্নাতের আটটি দরজাই খুলে দেওয়া হবে। সে নিজ ইচ্ছামত যে কোন দরজা দিয়েই তাতে যেতে পারবে। -সহীহ। ইবনু মাজাহ– (৪৭০)।",
