    "benefit": "আব্দুর রাহমান ইবনু আবূ বাকর বলেন, আমি আমার পিতাকে বললাম, হে আব্বাজান! আমি আপনাকে প্রতিদিন ভোরে ও সন্ধ্যায় তিনবার বলতে শুনিঃ ‘‘হে আল্লাহ! আমার দেহ সুস্থ রাখুন। হে আল্লাহ! আমাকে সুস্থ রাখুন আমার শ্রবণ ইন্দ্রিয়ে। হে আল্লাহ! আমাকে সুস্থ রাখুন আমার দৃষ্টিশক্তিতে। আপনি ছাড়া কোনো ইলাহ নেই।’’ তিনি বললেন, আমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে এ বাক্যগুলো দ্বারা দু‘আ করতে শুনেছি। সেজন্য আমিও তার নিয়ম অনুসরণ করতে ভালোবাসি। … আব্বাস (রাঃ)-এর বর্ণনায় রয়েছে তিনি বললেনঃ ‘‘হে আল্লাহ! আমি আপনার নিকট কুফরী ও দরিদ্রতা থেকে আশ্রয় চাইছি। হে আল্লাহ! আমি কবরের আযাব থেকে আপনার নিকট আশ্রয় চাইছি, আপনি ছাড়া অন্য কোনো ইলাহ নেই।’’ তিনি এ দু‘আ সকালে তিনবার ও সন্ধ্যায় তিনবার করে বলতেন।",
