    "arabic": "مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ",
    "benefit": "যায়দ ইবনু খালিদ জুহানী (রাযি.) হতে বর্ণিত … আল্লাহর রাসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ (রব) বলেন, আমার বান্দাদের মধ্য কেউ আমার প্রতি মু’মিন হয়ে গেল এবং কেউ কাফির। যে বলেছে, আল্লাহর করুণা ও রহমতে আমরা বৃষ্টি লাভ করেছি, সে হল আমার প্রতি বিশ্বাসী এবং নক্ষত্রের প্রতি অবিশ্বাসী। আর যে বলেছে, অমুক অমুক নক্ষত্রের প্রভাবে আমাদের উপর বৃষ্টিপাত হয়েছে, সে আমার প্রতি অবিশ্বাসী হয়েছে এবং নক্ষত্রের প্রতি বিশ্বাসী হয়েছে।",
    "reference": "সহীহ বুখারী: ৮৪৬",
    "durationMinutes": 1,
    "points": 4,
    "category": "dhikr",
    "timing": "বৃষ্টি হওয়ার পর"
