    "benefit": "যখন বাতাস প্রবল আকার ধারণ করত, তখন নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এভাবে দু'আ করতেনঃ “আল্ল-হুম্মা ইন্নী আসআলুকা খয়রাহা- ওয়া খয়রা মাকীহা- ওয়া খয়রা মা-ফীহা ওয়া খয়রা মা- উরসিলাত বিহী, ওয়া আউয়ুবিকা মিন শাররিহা- ওয়া শাররি মা- ফীহা- ওয়া শাররি মা-উরসিলাত বিহী” - (অর্থাৎ- হে আল্লাহ! আমি তোমার কাছে মেঘের কল্যাণ কামনা করছি ও এর মধ্যে যে কল্যাণ নিহিত আছে এবং যে কল্যাণের সাথে প্রেরিত হয়েছে তাও এবং তোমার কাছে এর অকল্যাণ ও এর মধ্যে যে অকল্যাণ নিহিত আছে এবং যে অকল্যাণ নিয়ে এসেছে তা থেকে আশ্রয় চাই।)।",
