    "arabic": "أَنَّ لِلَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَىْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى",
    "benefit": "উসামাহ ইবনু যায়দ (রাঃ) হতে বর্ণিত। তিনি বলেন, এক সময় আমরা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট ছিলাম। এমন সময় নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর কোন এক কন্যার পক্ষ থেকে একজন সংবাদবাহক এসে তাঁকে জানাল যে, তাঁর মেয়ের পুত্রের মৃত্যু যন্ত্রণা শুরু হয়েছে। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সংবাদবাহককে বলে দিলেন, তুমি ফিরে যাও এবং তাকে জানিয়ে দাও, আল্লাহ্ যা নিয়ে নিয়েছেন এবং তিনি যা দিয়ে রেখেছেন সবেরই তিনি মালিক। তাঁর কাছে প্রতিটি জিনিসের মেয়াদ সুনির্দিষ্ট। কাজেই তাকে গিয়ে ধৈর্য ধরতে এবং প্রতিফল পাওয়ার আশা করতে বল।",
    "reference": "সহীহ বুখারী: ৭৩৭৭",
