    "benefit": "'আবদুল্লাহ ইবনু বুসর (রাযিঃ) হতে বর্ণিত। … অতঃপর আমার আব্বা তার সওয়ারীর লাগাম ধরে বললেন, আপনি আমাদের জন্য আল্লাহর নিকট প্রার্থনা করুন। তখন তিনি বললেন, ইয়া আল্লাহ! তুমি তাদের রিযকে বারাকাত দাও, তাদের ক্ষমা করো এবং তাদের প্রতি দয়া করো।",
