    "benefit": "মুগীরাহ ইবনু শু‘বাহ (রাযি.)-এর কাতিব ওয়ার্রাদ (রাযি.) হতে বর্ণিত। তিনি বলেন, মুগীরাহ ইবনু শু‘বাহ (রাযি.) আমাকে দিয়ে মু‘আবিয়াহ (রাযি.)-কে একখানা পত্র লিখালেন যে, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম প্রত্যেক ফরজ সালাতের পর বলতেনঃ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهْوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ ‘‘এক আল্লাহ্ ব্যতীত কোন ইলাহ্ নেই, সার্বভৌমত্ব একমাত্র তাঁরই, সমস্ত প্রশংসা একমাত্র তাঁরই জন্য, তিনি সব কিছুর উপরই ক্ষমতাশীল। হে আল্লাহ্! আপনি যা প্রদান করতে চান তা রোধ করার কেউ নেই, আর আপনি যা রোধ করেন তা প্রদান করার কেউ নেই। আপনার নিকট (সৎকাজ ভিন্ন) কোন সম্পদশালীর সম্পদ উপকারে আসে না।’’",
