    "arabic": "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ",
    "benefit": "আবু হুরাইরাহ (রাযিঃ) থেকে বর্ণিত। তিনি বলেন, এক লোক নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এর নিকট এসে বলল, হে আল্লাহর রসূল সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম! গত রাতে একটি বিছু আমাকে দংশন করার কারণে আমি বড় কষ্ট পেয়েছি। তিনি বললেন, যদি তুমি সন্ধ্যায় এ দু’আটি পড়তে \"আউযু বিকালিমাতিল্লা-হিত তা-ম্মা-তি মিন শাররি মা- খলাক\" অৰ্থাৎ- ‘আমি পূর্ণাঙ্গ কালিমাহ দ্বারা আল্লাহর নিকট তার সৃষ্টির খারাবী থেকে পানাহ চাই’। তাহলে সে তোমাকে ক্ষতি করতে পারত না।",
    "reference": "সহীহ মুসলিম: ২৭০৯",
