    "benefit": "ইবনু ‘আব্বাস (রাঃ) হতে বর্ণিত। তিনি বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হাসান এবং হুসাইন (রাঃ)-এর জন্য নিম্নোক্ত দু‘আ পড়ে পানাহ চাইতেন আর বলতেন, তোমাদের পিতা ইবরাহীম (আঃ) ইসমাঈল ও ইসহাক (আঃ)-এর জন্য দু‘আ পড়ে পানাহ চাইতেন। আমি আল্লাহর পরিপূর্ণ কালিমার দ্বারা প্রত্যেক শয়তান, বিষাক্ত প্রাণী এবং প্রত্যেক কুদৃষ্টির অনিষ্ট হতে পানাহ চাচ্ছি।",
