    "benefit": "আবূ হুরাইরাহ্ (রাযি.) হতে বর্ণিত যে, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ ইমাম যখন ‘আমীন’ বলেন, তখন তোমরাও ‘আমীন’ বলো। কেননা, যার ‘আমীন’ (বলা) ও মালাইকাহর ‘আমীন’ (বলা) এক হয়, তার পূর্বের সব গুনাহ মা‘ফ করে দেয়া হয়।",
